+		}
+		for _, raw := range toolEntries(value) {
+			if _, _, scoped := spec.SplitPermissionRule(raw); scoped {
+				continue
+			}
+			for _, native := range bd.translateAgent(target, raw, entry).Native {
+				if keys[native] {
